61	/**
62	 * @author Vitaliy Fedoriv
63	 */
64	
65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    /**
71	     * Dedicated audit logger. On a successful owner create an audit line is emitted here carrying the
72	     * new owner's id, its assigned {@code memberId}, its {@code registrationDate} and its
73	     * numeric {@code membershipLevel}.
74	     */
75	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
76	
77	    /**
78	     * Dedicated notification logger. On a successful owner create a welcome notification is
79	     * enqueued here carrying the new owner's id and its assigned {@code memberId}.
80	     */
81	    private static final org.slf4j.Logger NOTIFY = org.slf4j.LoggerFactory.getLogger("NOTIFY");
82	
83	    /**
84	     * Monotonically increasing sequence assigned to each structured {@code OWNER_CREATED} audit event,
85	     * so the immutable event stream carries a strictly increasing {@code seq} across creates.
86	     */
87	    private static final java.util.concurrent.atomic.AtomicLong AUDIT_EVENT_SEQ =
88	        new java.util.concurrent.atomic.AtomicLong();
89	
90	    /**
91	     * Name of the optional request header carrying an idempotency token for owner creation.
92	     */
93	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
94	
95	    /**
96	     * Idempotency store mapping a previously seen {@code Idempotency-Key} to the id of the owner
97	     * originally created under it. When a create repeats with a key already present here, the
98	     * originally created owner is returned (200 OK) instead of creating a duplicate.
99	     */
100	    private final java.util.Map<String, Integer> idempotencyKeyToOwnerId =
101	        new java.util.concurrent.ConcurrentHashMap<>();
102	
103	    private final ClinicService clinicService;
104	
105	    private final OwnerMapper ownerMapper;
106	
107	    private final PetMapper petMapper;
108	
109	    private final VisitMapper visitMapper;
110	
111	    public OwnerRestControllerV1(ClinicService clinicService,
112	                                 OwnerMapper ownerMapper,
113	                                 PetMapper petMapper,
114	                                 VisitMapper visitMapper) {
115	        this.clinicService = clinicService;
116	        this.ownerMapper = ownerMapper;
117	        this.petMapper = petMapper;
118	        this.visitMapper = visitMapper;
119	    }
120	
121	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
122	    @Override
123	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
124	        Collection<Owner> owners;
125	        if (lastName != null) {
126	            owners = this.clinicService.findOwnerByLastName(lastName);
127	        } else {
128	            owners = this.clinicService.findAllOwners();
129	        }
130	        if (owners.isEmpty()) {
131	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
132	        }
133	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
139	        Owner owner = this.clinicService.findOwnerById(ownerId);
140	        if (owner == null) {
141	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
142	        }
143	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
144	    }
145	
146	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
147	    @Override
148	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
149	        String idempotencyKey = currentIdempotencyKey();
150	        if (idempotencyKey != null) {
151	            Integer existingId = idempotencyKeyToOwnerId.get(idempotencyKey);
152	            if (existingId != null) {
153	                Owner existing = this.clinicService.findOwnerById(existingId);
154	                if (existing != null) {
155	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
156	                }
157	            }
158	        }
159	        HttpHeaders headers = new HttpHeaders();
160	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
161	        applyAddress(owner, ownerFieldsDto);
162	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
163	        rejectFutureRegistrationDate(registrationDate);
164	        if (registrationDate == null) {
165	            registrationDate = java.time.LocalDate.now();
166	        }
167	        registrationDate = toBusinessDay(registrationDate);
168	        owner.setRegistrationDate(registrationDate);
169	        rejectDailyLimitReached(registrationDate);
170	        rejectCityAtCapacity(owner.getCity());
171	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
172	        owner.setTelephone(telephone);
173	        String email = normalizeEmail(ownerFieldsDto.getEmail());
174	        owner.setEmail(email);
175	        owner.setPostcode(validatePostcode(owner.getCity(), ownerFieldsDto.getPostcode()));
176	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
177	        rejectDuplicateIdentity(owner);
178	        // Joining an existing household is now permitted (an exact-identity duplicate is still
179	        // rejected above); a joiner's membershipLevel is instead capped one above the household's
180	        // current maximum (see cappedMembershipLevel).
181	        String region = Localities.region(owner.getPostcode(), owner.getCity());
182	        owner.setMemberId(assignMemberId(region, owner.getTelephone(), owner.getLastName(), registrationDate));
183	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
184	        owner.setBulkSignupWarning(computeBulkSignupWarning(registrationDate));
185	        owner.setCapacityWarning(computeCapacityWarning(owner.getCity()));
186	        owner.setHouseholdSize(countHouseholdMembers(owner.getLastName(), owner.getPostcode()) + 1);
187	        owner.setMembershipLevel(cappedMembershipLevel(owner));
188	        // A declared household member (sharesHousehold) is created but is not a suspected duplicate.
189	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicateOf(owner);
190	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
191	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
192	        this.clinicService.saveOwner(owner);
193	        if (idempotencyKey != null) {
194	            idempotencyKeyToOwnerId.put(idempotencyKey, owner.getId());
195	        }
196	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
197	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
198	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
199	            ownerDto.getMembershipLevel());
200	        AUDIT.info(ownerCreatedEvent(owner, ownerDto));
201	        NOTIFY.info("welcome notification enqueued ownerId={} memberId={}",
202	            owner.getId(), owner.getMemberId());
203	        headers.setLocation(UriComponentsBuilder.newInstance()
204	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
205	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
206	    }
207	
208	    /**
209	     * Builds the immutable structured {@code OWNER_CREATED} audit event emitted (in addition to the
210	     * human-readable audit line) on a successful create, as a JSON object
211	     * {@code {seq, ownerId, memberId, membershipLevel, event:'OWNER_CREATED'}}. The {@code seq} is
212	     * a fresh value from the monotonically increasing {@link #AUDIT_EVENT_SEQ} sequence, so the event
213	     * stream is strictly ordered across creates.
214	     * <p>
215	     * The {@code memberId} field carries the owner's current primary identifier (see
216	     * {@link #primaryIdentifier}), so the event always names the owner by its live primary identifier.
217	     *
218	     * @param owner the just-saved owner
219	     * @param ownerDto the mapped DTO, used for the (possibly derived) {@code membershipLevel}
220	     * @return the JSON-encoded structured event
221	     */
222	    private String ownerCreatedEvent(Owner owner, OwnerDto ownerDto) {
223	        StringBuilder json = new StringBuilder(128);
224	        json.append('{');
225	        json.append("\"seq\":").append(AUDIT_EVENT_SEQ.incrementAndGet());
226	        json.append(",\"ownerId\":").append(owner.getId());
227	        json.append(",\"memberId\":").append(jsonString(primaryIdentifier(owner)));
228	        json.append(",\"membershipLevel\":").append(ownerDto.getMembershipLevel());
229	        json.append(",\"event\":\"OWNER_CREATED\"");
230	        json.append('}');
231	        return json.toString();
232	    }
233	
234	    /**
235	     * The owner's current primary identifier carried by the structured audit event: the assigned
236	     * {@code memberId}.
237	     *
238	     * @param owner the just-saved owner
239	     * @return the owner's live primary identifier
240	     */
241	    private String primaryIdentifier(Owner owner) {
242	        return owner.getMemberId();
243	    }
244	
245	    /**
246	     * Encodes a value as a JSON string literal (quoted, with the JSON-significant characters escaped),
247	     * or the literal {@code null} when the value is absent.
248	     */
249	    private static String jsonString(String value) {
250	        if (value == null) {
251	            return "null";
252	        }
253	        StringBuilder sb = new StringBuilder(value.length() + 2);
254	        sb.append('"');
255	        for (int i = 0; i < value.length(); i++) {
256	            char c = value.charAt(i);
257	            switch (c) {
258	                case '"' -> sb.append("\\\"");
259	                case '\\' -> sb.append("\\\\");
260	                case '\n' -> sb.append("\\n");
261	                case '\r' -> sb.append("\\r");
262	                case '\t' -> sb.append("\\t");
263	                default -> {
264	                    if (c < 0x20) {
265	                        sb.append(String.format("\\u%04x", (int) c));
266	                    } else {
267	                        sb.append(c);
268	                    }
269	                }
270	            }
271	        }
272	        sb.append('"');
273	        return sb.toString();
274	    }
275	
276	    /**
277	     * Reads the optional {@code Idempotency-Key} header from the current request, if any. A create
278	     * carrying this header is idempotent: the first create under a key is recorded, and a later create
279	     * with the same key returns the originally created owner instead of creating a duplicate.
280	     *
281	     * @return the trimmed idempotency key, or {@code null} when the header is absent, blank or there is
282	     *         no active servlet request
283	     */
284	    private String currentIdempotencyKey() {
285	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
286	        if (attributes instanceof ServletRequestAttributes servletAttributes) {
287	            String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
288	            if (key != null && !key.isBlank()) {
289	                return key.trim();
290	            }
291	        }
292	        return null;
293	    }
294	
295	    /**
296	     * Rejects creating an owner whose supplied {@code registrationDate} is later than the server
297	     * date (in the future). Only an explicitly supplied date is validated; a {@code null} date
298	     * (which later defaults to the server date) is accepted. The check is against the raw supplied
299	     * date, before any business-day adjustment.
300	     *
301	     * @param registrationDate the supplied registration date, or {@code null} when none was supplied
302	     * @throws FutureRegistrationDateException (400 Bad Request) if the supplied date is in the future
303	     */
304	    private void rejectFutureRegistrationDate(java.time.LocalDate registrationDate) {
305	        if (registrationDate != null && registrationDate.isAfter(java.time.LocalDate.now())) {
306	            throw new FutureRegistrationDateException(registrationDate);
307	        }
308	    }
309	
310	    /**
311	     * The maximum number of owners that may be created in a single day. Creating an owner once this
312	     * many owners already carry today's {@code registrationDate} is rejected.
313	     */
314	    private static final int DAILY_OWNER_LIMIT = 100;
315	
316	    /**
317	     * Rejects creating an owner once {@value #DAILY_OWNER_LIMIT} or more owners already carry the
318	     * given business day as their {@code registrationDate}. The count is keyed by the
319	     * business-day-adjusted registration date of the owner being created (see
320	     * {@link #toBusinessDay}), so all owners falling on the same business day count together. Owners
321	     * with no {@code registrationDate} are ignored.
322	     *
323	     * @param registrationDate the business-day-adjusted registration date of the owner being created
324	     * @throws DailyOwnerLimitException (429 Too Many Requests) if the daily limit is already reached
325	     */
326	    private void rejectDailyLimitReached(java.time.LocalDate registrationDate) {
327	        long count = this.clinicService.findAllOwners().stream()
328	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
329	            .count();
330	        if (count >= DAILY_OWNER_LIMIT) {
331	            throw new DailyOwnerLimitException(registrationDate);
332	        }
333	    }
334	
335	    /**
336	     * The threshold of owners already created on a business day beyond which a bulk-signup warning is
337	     * raised on a new owner. Once strictly more than this many owners already carry the day as their
338	     * {@code registrationDate}, the new owner's {@code bulkSignupWarning} is set to {@code true}.
339	     */
340	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
341	
342	    /**
343	     * Computes the {@code bulkSignupWarning} for an owner being created: {@code true} when more than
344	     * {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created today, otherwise
345	     * {@code false}. Existing owners are counted the same way the daily-limit rule counts them (see
346	     * {@link #rejectDailyLimitReached}), keyed by the business-day-adjusted registration date, and the
347	     * owner being created is excluded (it has not yet been saved).
348	     *
349	     * @param registrationDate the business-day-adjusted registration date of the owner being created
350	     * @return {@code true} if more than the threshold of owners already carry this business day
351	     */
352	    private boolean computeBulkSignupWarning(java.time.LocalDate registrationDate) {
353	        long count = this.clinicService.findAllOwners().stream()
354	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
355	            .count();
356	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
357	    }
358	
359	    /**
360	     * The fixed public holidays the business-day roll skips. A registration date landing on any of
361	     * these dates is rolled forward, just as it is for a weekend.
362	     */
363	    private static final java.util.Set<java.time.LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
364	        java.time.LocalDate.parse("2026-01-01"),
365	        java.time.LocalDate.parse("2026-01-26"),
366	        java.time.LocalDate.parse("2026-04-25"),
367	        java.time.LocalDate.parse("2026-12-25"),
368	        java.time.LocalDate.parse("2026-12-28"));
369	
370	    /**
371	     * Rolls a registration date forward onto a business day: a Saturday, Sunday or listed public
372	     * holiday is moved forward to the next non-holiday weekday; an ordinary weekday is returned
373	     * unchanged. This applies to the effective registration date whether it was supplied in the
374	     * request or defaulted to the server date, and every value derived from the registration date
375	     * uses the adjusted result.
376	     *
377	     * @param date the effective registration date
378	     * @return {@code date} itself when it is a non-holiday weekday, otherwise the next business day
379	     */
380	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
381	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
382	            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
383	            || PUBLIC_HOLIDAYS.contains(date)) {
384	            date = date.plusDays(1);
385	        }
386	        return date;
387	    }
388	
389	    /**
390	     * The maximum number of owners a single city may contain. Creating an owner in a city that
391	     * already holds this many owners is rejected.
392	     */
393	    private static final int CITY_CAPACITY = 50;
394	
395	    /**
396	     * Rejects creating an owner whose city already contains {@value #CITY_CAPACITY} or more owners.
397	     * Owners are counted per city comparing the city name case-insensitively (a {@code null} city is
398	     * treated as empty).
399	     *
400	     * @param city the city of the owner being created
401	     * @throws CityAtCapacityException (409 Conflict) if the city is already at capacity
402	     */
403	    private void rejectCityAtCapacity(String city) {
404	        String cityValue = city == null ? "" : city;
405	        long count = this.clinicService.findAllOwners().stream()
406	            .filter(existing -> cityValue.equalsIgnoreCase(
407	                existing.getCity() == null ? "" : existing.getCity()))
408	            .count();
409	        if (count >= CITY_CAPACITY) {
410	            throw new CityAtCapacityException(city);
411	        }
412	    }
413	
414	    /**
415	     * The number of owners a city must already hold for a new owner in it to raise a
416	     * {@code capacityWarning}. Once a city holds at least this many owners (but fewer than the hard
417	     * {@link #CITY_CAPACITY} limit) the next owner created in it warns that the city is approaching
418	     * capacity.
419	     */
420	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
421	
422	    /**
423	     * Computes the {@code capacityWarning} for an owner being created: {@code true} when the owner's
424	     * city already holds between {@value #CITY_CAPACITY_WARNING_THRESHOLD} and
425	     * {@value #CITY_CAPACITY} minus one owners (approaching, but not yet at, the hard
426	     * {@link #CITY_CAPACITY} limit), otherwise {@code false}. Owners are counted per city the same way
427	     * the hard capacity rule counts them (see {@link #rejectCityAtCapacity}), comparing the city name
428	     * case-insensitively with a {@code null} city treated as empty, and the owner being created is
429	     * excluded (it has not yet been saved). A city already at or beyond the hard limit is rejected
430	     * before this runs, so it never reports a warning.
431	     *
432	     * @param city the city of the owner being created
433	     * @return {@code true} if the city is approaching its capacity limit
434	     */
435	    private boolean computeCapacityWarning(String city) {
436	        String cityValue = city == null ? "" : city;
437	        long count = this.clinicService.findAllOwners().stream()
438	            .filter(existing -> cityValue.equalsIgnoreCase(
439	                existing.getCity() == null ? "" : existing.getCity()))
440	            .count();
441	        return count >= CITY_CAPACITY_WARNING_THRESHOLD && count < CITY_CAPACITY;
442	    }
443	
444	    /**
445	     * Assigns an owner's {@code memberId} on create, formatted {@code '<REGION><FY><HASH8><CHK>'}: the
446	     * owner's canonical region REGION (derived by preferring the postcode, see
447	     * {@link Localities#region(String, String)} — the same region derivation shared with the
448	     * {@code locality}); the 2-digit fiscal year FY of the registration date (see
449	     * {@link org.springframework.samples.petclinic.util.FiscalYears#fiscalYear(java.time.LocalDate)});
450	     * the first 8 upper-case hex characters HASH8 of the SHA-256 digest of the normalized (E.164)
451	     * telephone concatenated with the last name (the same HASH8 used by the region-and-hash identity);
452	     * and a single Luhn check digit CHK computed over the decimal digits contained in
453	     * {@code <REGION><FY><HASH8>} (e.g. {@code 'NSW263A7F9C2E5'}). The id is derived from the owner's
454	     * own identity fields; it carries no sequence number.
455	     * <p>
456	     * When the computed id collides with an existing owner's {@code memberId}, it is de-duplicated by
457	     * appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes it unique (e.g.
458	     * {@code 'NSW263A7F9C2E5-2'}), and the de-duplicated id is returned.
459	     *
460	     * @param region the owner's canonical region (the identity's REGION, shared with the locality)
461	     * @param telephone the owner's normalized (E.164) telephone
462	     * @param lastName the owner's last name
463	     * @param registrationDate the owner's business-day-adjusted registration date (supplies FY)
464	     * @return the assigned member id, de-duplicated to be unique among existing owners
465	     */
466	    private String assignMemberId(String region, String telephone, String lastName,
467	            java.time.LocalDate registrationDate) {
468	        String basis = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
469	        String hash8 = sha256UpperHex(basis).substring(0, 8);
470	        String fy = String.format("%02d",
471	            org.springframework.samples.petclinic.util.FiscalYears.fiscalYear(registrationDate) % 100);
472	        String base = region + fy + hash8;
473	        String memberId = base
474	            + org.springframework.samples.petclinic.util.CheckDigits.luhn(base);
475	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
476	            .map(Owner::getMemberId)
477	            .filter(java.util.Objects::nonNull)
478	            .collect(java.util.stream.Collectors.toSet());
479	        if (!existing.contains(memberId)) {
480	            return memberId;
481	        }
482	        for (int n = 2; ; n++) {
483	            String candidate = memberId + "-" + n;
484	            if (!existing.contains(candidate)) {
485	                return candidate;
486	            }
487	        }
488	    }
