490	    /**
491	     * Returns the full upper-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
492	     */
493	    private static String sha256UpperHex(String value) {
494	        try {
495	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
496	                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
497	            StringBuilder sb = new StringBuilder(digest.length * 2);
498	            for (byte b : digest) {
499	                sb.append(String.format("%02X", b));
500	            }
501	            return sb.toString();
502	        }
503	        catch (java.security.NoSuchAlgorithmException e) {
504	            throw new IllegalStateException("SHA-256 not available", e);
505	        }
506	    }
