545	    /**
546	     * Computes the {@code membershipLevel} to store for the owner being created, applying the household
547	     * ceiling. The owner's natural level is first derived from their own fields (see
548	     * {@link org.springframework.samples.petclinic.util.Memberships#membershipLevel(String, Integer, Integer, java.time.LocalDate)}).
549	     * It is then capped so it cannot exceed one above the current maximum {@code membershipLevel} among
550	     * the owner's existing household members (the non-deleted owners sharing its {@code householdId}, see
551	     * {@link Households#householdId}). When the owner has no existing household member no cap applies and
552	     * the natural level is returned.
553	     *
554	     * @param owner the owner being created, with its level-affecting fields already populated
555	     * @return the (possibly capped) membership level to store on the owner
556	     */
557	    private int cappedMembershipLevel(Owner owner) {
558	        int naturalLevel = org.springframework.samples.petclinic.util.Memberships.membershipLevel(
559	            owner.getEmail(), owner.getNamesakeCount(), owner.getHouseholdSize(), owner.getRegistrationDate());
560	        String householdId = Households.householdId(owner.getLastName(), owner.getPostcode());
561	        java.util.OptionalInt maxMemberLevel = this.clinicService.findAllOwners().stream()
562	            .filter(this::isNotDeleted)
563	            .filter(existing -> householdId.equals(
564	                Households.householdId(existing.getLastName(), existing.getPostcode())))
565	            .mapToInt(this::effectiveMembershipLevel)
566	            .max();
567	        if (maxMemberLevel.isEmpty()) {
568	            return naturalLevel;
569	        }
570	        return Math.min(naturalLevel, maxMemberLevel.getAsInt() + 1);
571	    }
