573	    /**
574	     * Returns an existing owner's effective {@code membershipLevel}: the stored value when present (the
575	     * value assigned, and possibly capped, when that owner was created), otherwise the level derived
576	     * from its own fields for owners that predate the stored level (e.g. seed data).
577	     *
578	     * @param owner an existing owner
579	     * @return the owner's effective membership level
580	     */
581	    private int effectiveMembershipLevel(Owner owner) {
582	        if (owner.getMembershipLevel() != null) {
583	            return owner.getMembershipLevel();
584	        }
585	        return org.springframework.samples.petclinic.util.Memberships.membershipLevel(
586	            owner.getEmail(), owner.getNamesakeCount(), owner.getHouseholdSize(), owner.getRegistrationDate());
587	    }
