589	    /**
590	     * Finds the existing owner, if any, that the owner being created is a soft duplicate of: an owner
591	     * sharing this owner's {@code soundex(lastName)} and postcode (an exact match of the stored 4-digit
592	     * value) while carrying a <em>different</em> {@code identityKey}. A soft match is distinct from the
593	     * hard duplicate rejected earlier by {@link #rejectDuplicateIdentity} (which requires an identical
594	     * identity key): the owner is still created, but flagged. Because the telephone is part of the
595	     * identity key, two owners with the same last name and postcode but different telephones are a soft
596	     * match rather than a hard duplicate. When more than one existing owner matches, the earliest
597	     * (lowest id) is returned so the reference is deterministic. An owner with no postcode can never
598	     * soft-match.
599	     *
600	     * @param owner the owner being created, with its telephone and postcode already normalized/validated
601	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
602	     */
603	    private Integer findPossibleDuplicateOf(Owner owner) {
604	        String postcode = owner.getPostcode();
605	        if (postcode == null) {
606	            return null;
607	        }
608	        String soundex = Households.soundex(owner.getLastName());
609	        String identity = Households.identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
610	        return this.clinicService.findAllOwners().stream()
611	            .filter(this::isNotDeleted)
612	            .filter(existing -> soundex.equals(Households.soundex(existing.getLastName())))
613	            .filter(existing -> postcode.equals(existing.getPostcode()))
614	            .filter(existing -> !identity.equals(Households.identityKey(
615	                toE164OrNull(existing.getTelephone()), existing.getEmail(), existing.getLastName())))
616	            .map(Owner::getId)
617	            .filter(java.util.Objects::nonNull)
618	            .min(java.util.Comparator.naturalOrder())
619	            .orElse(null);
620	    }
