622	    /**
623	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
624	     * stripped. A leading '+' and its country code are kept as given; otherwise country code '+61' is
625	     * assumed and a single leading '0' is dropped from the national digits. The resulting number must
626	     * have 8 to 15 digits after the '+'. For example {@code "0412 345 678"} becomes
627	     * {@code "+61412345678"}. The E.164 value is stored and returned.
628	     * <p>
629	     * The national-number length (the digits after the country code) is additionally validated for
630	     * country codes with a fixed length: '+61' requires exactly 9 national digits and '+1' requires
631	     * exactly 10. Numbers of other country codes are only bound by the overall 8-to-15-digit limit.
632	     *
633	     * @param telephone the raw telephone as submitted
634	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
635	     * @throws InvalidTelephoneException (400 Bad Request) if the value cannot form a valid E.164 number
636	     *         or its national-number length is wrong for its country code
637	     */
638	    private String normalizeTelephone(String telephone) {
639	        String raw = telephone == null ? "" : telephone.trim();
640	        boolean hasCountryCode = raw.startsWith("+");
641	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
642	        if (hasCountryCode) {
643	            cleaned = cleaned.substring(1);
644	        }
645	        String digits;
646	        if (hasCountryCode) {
647	            digits = cleaned;
648	        } else {
649	            if (cleaned.startsWith("0")) {
650	                cleaned = cleaned.substring(1);
651	            }
652	            digits = "61" + cleaned;
653	        }
654	        if (!digits.matches("[0-9]{8,15}") || !hasValidNationalLength(digits)) {
655	            throw new InvalidTelephoneException(telephone);
656	        }
657	        return "+" + digits;
658	    }
659	
660	    /**
661	     * Checks the national-number length of an E.164 digit string against its country code for the
662	     * country codes whose national number has a fixed length: '+61' requires 9 national digits and
663	     * '+1' requires 10. Any other country code passes, leaving it bound only by the overall length.
664	     *
665	     * @param digits the E.164 digits (the country code followed by the national number, without '+')
666	     * @return {@code true} if the national-number length is acceptable for the country code
667	     */
668	    private boolean hasValidNationalLength(String digits) {
669	        if (digits.startsWith("61")) {
670	            return digits.length() - 2 == 9;
671	        }
672	        if (digits.startsWith("1")) {
673	            return digits.length() - 1 == 10;
674	        }
675	        return true;
676	    }
