678	    /**
679	     * Syntactic email pattern: a non-empty local part, an '@', a domain with at least one dot and a
680	     * multi-character top-level label. Deliberately lenient about the exact character set while still
681	     * rejecting values that are clearly not addresses (e.g. missing '@').
682	     */
683	    private static final java.util.regex.Pattern EMAIL_PATTERN =
684	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$");
685	
686	    /**
687	     * Domains of known disposable/throwaway email providers. An owner whose email domain is on this
688	     * blocklist is rejected with a 400 Bad Request. Compared case-insensitively against the
689	     * lower-cased email domain.
690	     */
691	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
692	        "mailinator.com", "tempmail.com", "guerrillamail.com");
693	
694	    /**
695	     * Normalizes an owner's email. Email is optional: a {@code null} or blank value is left as
696	     * {@code null} (no email). When present it must be a syntactically valid address; the value is
697	     * lower-cased before being stored and returned.
698	     *
699	     * @param email the raw email as submitted, may be {@code null}
700	     * @return the lower-cased email, or {@code null} when none was supplied
701	     * @throws InvalidEmailException (400 Bad Request) if a non-blank value is not a valid address
702	     */
703	    private String normalizeEmail(String email) {
704	        if (email == null || email.isBlank()) {
705	            return null;
706	        }
707	        String trimmed = email.trim();
708	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
709	            throw new InvalidEmailException(email);
710	        }
711	        String normalized = trimmed.toLowerCase(java.util.Locale.ROOT);
712	        String domain = normalized.substring(normalized.indexOf('@') + 1);
713	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
714	            throw new DisposableEmailException(email);
715	        }
716	        return normalized;
717	    }
