719	    /**
720	     * Fixed region-to-postcode-range table: a region's postcode must fall within its inclusive range
721	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city whose region is not listed here (see
722	     * {@link Localities#region}) accepts any 4-digit postcode.
723	     */
724	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
725	        "NSW", new int[] {2000, 2099},
726	        "VIC", new int[] {3000, 3099},
727	        "QLD", new int[] {4000, 4099});
728	
729	    /**
730	     * Validates an owner's postcode on create. The postcode is optional: a {@code null} or blank value
731	     * is left as {@code null} (no postcode) and accepted. When present it must be exactly 4 digits and,
732	     * for a city whose region is in the fixed {@link #REGION_POSTCODE_RANGES range table}, must fall
733	     * within that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no
734	     * known region accepts any 4-digit postcode. The value is stored and returned exactly as supplied.
735	     *
736	     * @param city the owner's city, used to derive the region whose range constrains the postcode
737	     * @param postcode the raw postcode as submitted, may be {@code null}
738	     * @return the postcode when supplied, or {@code null} when none was supplied
739	     * @throws InvalidPostcodeException (400 Bad Request) if a supplied postcode is not 4 digits or is
740	     *         out of range for the city's region
741	     */
742	    private String validatePostcode(String city, String postcode) {
743	        if (postcode == null || postcode.isBlank()) {
744	            return null;
745	        }
746	        if (!postcode.matches("[0-9]{4}")) {
747	            throw new InvalidPostcodeException(postcode);
748	        }
749	        int[] range = REGION_POSTCODE_RANGES.get(Localities.region(city));
750	        if (range != null) {
751	            int value = Integer.parseInt(postcode);
752	            if (value < range[0] || value > range[1]) {
753	                throw new InvalidPostcodeException(postcode);
754	            }
755	        }
756	        return postcode;
757	    }
