759	    /**
760	     * Common street-type abbreviations expanded to their full word during address normalization.
761	     */
762	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS = java.util.Map.of(
763	        "ST", "STREET",
764	        "RD", "ROAD",
765	        "AVE", "AVENUE");
766	
767	    /**
768	     * Applies the owner's address on create from the structured fields when present, falling back to the
769	     * flat {@code address} for backward compatibility. An owner must supply an address in at least one
770	     * form: a non-blank {@code addressLine1} (the structured form, preferred) or a non-blank flat
771	     * {@code address}; when neither is present the create is rejected.
772	     * <p>
773	     * Whichever address fields are supplied are normalized (see {@link #normalizeAddress}). When the
774	     * structured form is used the normalized {@code addressLine1} and, when supplied, {@code addressLine2}
775	     * are stored on the owner and the composed {@code address} is the normalized {@code addressLine1} with
776	     * a single space and the normalized {@code addressLine2} appended when {@code addressLine2} is present.
777	     * When only the flat form is used the normalized flat value becomes the stored {@code address} and the
778	     * structured lines are left unset. The stored {@code address} is the value every later step reads.
779	     *
780	     * @param owner the owner being created
781	     * @param ownerFieldsDto the submitted owner fields carrying the raw address input
782	     * @throws InvalidAddressException (400 Bad Request) if no address is supplied in either form
783	     */
784	    private void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
785	        String rawLine1 = ownerFieldsDto.getAddressLine1();
786	        String rawLine2 = ownerFieldsDto.getAddressLine2();
787	        String rawFlat = ownerFieldsDto.getAddress();
788	        boolean hasLine1 = rawLine1 != null && !rawLine1.isBlank();
789	        boolean hasFlat = rawFlat != null && !rawFlat.isBlank();
790	        if (!hasLine1 && !hasFlat) {
791	            throw new InvalidAddressException(rawLine1 != null ? rawLine1 : rawFlat);
792	        }
793	        if (hasLine1) {
794	            String line1 = normalizeAddress(rawLine1);
795	            String line2 = (rawLine2 != null && !rawLine2.isBlank()) ? normalizeAddress(rawLine2) : null;
796	            owner.setAddressLine1(line1);
797	            owner.setAddressLine2(line2);
798	            owner.setAddress(line2 != null ? line1 + " " + line2 : line1);
799	        } else {
800	            owner.setAddressLine1(null);
801	            owner.setAddressLine2(null);
802	            owner.setAddress(normalizeAddress(rawFlat));
803	        }
804	    }
