806	    /**
807	     * Normalizes an owner's address on create. Surrounding whitespace is trimmed and internal runs of
808	     * whitespace collapse to a single space, the value is upper-cased and common street-type
809	     * abbreviations are expanded to their full word ({@code ST} to {@code STREET}, {@code RD} to
810	     * {@code ROAD}, {@code AVE} to {@code AVENUE}). For example {@code "  12  main  st "} becomes
811	     * {@code "12 MAIN STREET"}. The normalized value is stored and returned, and is also the form used
812	     * for every address comparison (household duplicate detection and the shared household id).
813	     *
814	     * @param address the raw address as submitted
815	     * @return the normalized address
816	     * @throws InvalidAddressException (400 Bad Request) if the address is blank after normalization
817	     */
818	    private String normalizeAddress(String address) {
819	        String collapsed = (address == null ? "" : address).trim().replaceAll("\\s+", " ");
820	        if (collapsed.isEmpty()) {
821	            throw new InvalidAddressException(address);
822	        }
823	        String[] tokens = collapsed.toUpperCase(java.util.Locale.ROOT).split(" ");
824	        StringBuilder normalized = new StringBuilder(collapsed.length());
825	        for (int i = 0; i < tokens.length; i++) {
826	            if (i > 0) {
827	                normalized.append(' ');
828	            }
829	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
830	        }
831	        return normalized.toString();
832	    }
