863	    /**
864	     * Whether an existing owner is not soft-deleted. A soft-deleted owner (its {@code deleted} flag
865	     * set) is retained but ignored by the create endpoint's duplicate and identity checks, so a
866	     * normally-blocking duplicate is allowed when the only matching owner has been deleted.
867	     */
868	    private boolean isNotDeleted(Owner owner) {
869	        return !Boolean.TRUE.equals(owner.getDeleted());
870	    }
