872	    /**
873	     * Normalizes an existing owner's telephone to E.164 for duplicate comparison, returning
874	     * {@code null} instead of throwing when the stored value cannot form a valid E.164 number, or
875	     * when its national-number length does not match its country code.
876	     */
877	    private String toE164OrNull(String telephone) {
878	        try {
879	            return normalizeTelephone(telephone);
880	        } catch (InvalidTelephoneException e) {
881	            return null;
882	        }
883	    }
